import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());
        System.out.println(computeApp(n, M));
    }

    static int extendedGCD(int a, int b, int[] xy) {
        int r0 = a, r1 = b;
        int s0 = 1, s1 = 0;
        int t0 = 0, t1 = 1;
        while (r1 != 0) {
            int q = r0 / r1;
            int rTemp = r0 - q * r1;
            r0 = r1;
            r1 = rTemp;

            int sTemp = s0 - q * s1;
            s0 = s1;
            s1 = sTemp;

            int tTemp = t0 - q * t1;
            t0 = t1;
            t1 = tTemp;
        }
        xy[0] = s0;
        xy[1] = t0;
        return r0;
    }

    static int[] factorialCoeffs(int n, int M) {
        int[] coeffs = new int[n + 1];
        Arrays.fill(coeffs, 0);
        coeffs[n] = 1;
        for (int k = n - 1; k >= 0; k--) {
            coeffs[k] = (int)(((long)coeffs[k + 1] * (k + 1)) % M);
            if (coeffs[k] == 0) {
                break;
            }
        }
        return coeffs;
    }

    static int computeApp(int n, int M) {
        List<List<int[]>> K = new ArrayList<>();
        List<int[]> firstLayer = new ArrayList<>();
        firstLayer.add(new int[] {1});
        K.add(firstLayer);
        for (int i = 0; i < n - 1; i++) {
            List<int[]> prevLayer = K.get(i);
            int sizePrev = prevLayer.size();
            List<int[]> newLayer = new ArrayList<>();
            for (int j = 0; j < sizePrev + i + 1; j++) {
                int[] row = new int[i + 2];
                for (int k = 0; k < i + 2; k++) {
                    row[k] = 0;
                }
                newLayer.add(row);
            }
            K.add(newLayer);
            for (int j = 0; j < sizePrev; j++) {
                int[] rowPrev = prevLayer.get(j);
                int lenRow = rowPrev.length;
                for (int k = 0; k < lenRow; k++) {
                    int val = rowPrev[k];
                    for (int h = 0; h < i + 1; h++) {
                        int[] targetRow = K.get(j + h);
                        targetRow[k] = (int)(( (long)targetRow[k] + val) % M);
                    }
                    int[] targetRow = K.get(j + i + 1);
                    targetRow[i + 1] = (int)(( (long)targetRow[i + 1] + val) % M);
                }
            }
        }
        int[] C = factorialCoeffs(n, M);
        long totalSum = 0;
        for (int i = 1; i < n; i++) {
            List<int[]> currentLayer = K.get(i);
            int ni = currentLayer.size();
            int mi = currentLayer.get(0).length;
            int[][] S = new int[ni][mi];
            for (int j = 0; j < ni; j++) {
                System.arraycopy(currentLayer.get(j), 0, S[j], 0, mi);
            }

            // Reverse cumulative sum horizontally
            for (int j = 0; j < ni; j++) {
                for (int k = mi - 2; k >= 0; k--) {
                    S[j][k] = (S[j][k] + S[j][k + 1]) % M;
                }
            }
            // Vertical cumulative sum
            for (int j = 1; j < ni; j++) {
                for (int k = 0; k < mi; k++) {
                    S[j][k] = (S[j][k] + S[j - 1][k]) % M;
                }
            }

            long s_value = 0;
            for (int j = 1; j < ni; j++) {
                int[] rowJ = currentLayer.get(j);
                for (int k = 0; k < mi - 1; k++) {
                    long product = ((long)rowJ[k] * S[j - 1][k + 1]) % M;
                    s_value = (s_value + product) % M;
                }
            }
            int c = C[i + 1];
            s_value = (s_value * c) % M;
            totalSum = (totalSum + s_value) % M;
        }
        return (int)totalSum;
    }
}
